arguments.file_text:
namespace sv_6ee6ed0400fd4cc59d2806b3ef6eeb25.Models;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);

public record NotificationPrefs(
    bool EmailNotifications,
    bool PushNotifications,
    bool WeeklyDigest,
    List<string> MutedChannels);

public record SecuritySettings(
    bool TwoFactorEnabled,
    DateTime? LastPasswordChange,
    List<ActiveSession> Sessions);

public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);

public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@rendermode InteractiveServer
@using sv_6ee6ed0400fd4cc59d2806b3ef6eeb25.Models
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <!-- Left sidebar navigation -->
    <nav class="settings-sidebar">
        <h5 class="sidebar-title">Settings</h5>
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="nav-item">
                    <button class="nav-link @(ActiveSection == section.Key ? "active" : "")"
                            @onclick="() => ActiveSection = section.Key">
                        <span class="nav-icon">@section.Icon</span>
                        @section.Label
                    </button>
                </li>
            }
        </ul>
    </nav>

    <!-- Main content area -->
    <div class="settings-content">
        @if (_loading)
        {
            <div class="text-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            <!-- Toast message -->
            @if (!string.IsNullOrEmpty(_toastMessage))
            {
                <div class="alert @(_toastIsError ? "alert-danger" : "alert-success") alert-dismissible fade show toast-message" role="alert">
                    @_toastMessage
                    <button type="button" class="btn-close" @onclick="DismissToast"></button>
                </div>
            }

            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }
    </div>
</div>

<!-- Revoke Session Confirmation Modal -->
@if (_showRevokeConfirm)
{
    <div class="modal-backdrop fade show"></div>
    <div class="modal fade show d-block" tabindex="-1" role="dialog">
        <div class="modal-dialog modal-dialog-centered" role="document">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke?.Device</strong> from <strong>@_sessionToRevoke?.Location</strong>?</p>
                    <p class="text-muted mb-0">This will sign out that device immediately.</p>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    <button type="button" class="btn btn-danger" @onclick="ConfirmRevoke" disabled="@_revoking">
                        @if (_revoking)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                        }
                        Revoke Session
                    </button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    // Section definitions
    private record SectionInfo(string Key, string Label, string Icon);

    private readonly SectionInfo[] _sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨")
    ];

    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    // Toast
    private string? _toastMessage;
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    // Profile state
    private UserProfile? _savedProfile;
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    // Notification state
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _allChannels = ["general", "announcements", "engineering", "design", "marketing", "support", "random"];
    private HashSet<string> _mutedChannels = [];

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _changingPassword;
    private bool _showRevokeConfirm;
    private ActiveSession? _sessionToRevoke;
    private bool _revoking;

    // Appearance state
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Korean", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        // Profile
        _savedProfile = await profileTask;
        ApplyProfile(_savedProfile);

        // Notifications
        var notif = await notifTask;
        _emailNotifications = notif.EmailNotifications;
        _pushNotifications = notif.PushNotifications;
        _weeklyDigest = notif.WeeklyDigest;
        _mutedChannels = new HashSet<string>(notif.MutedChannels);

        // Security
        _securitySettings = await securityTask;

        // Appearance
        var appearance = await appearanceTask;
        _theme = appearance.Theme;
        _fontSize = appearance.FontSize;
        _language = appearance.Language;
        _compactMode = appearance.CompactMode;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    // --- Toast helpers ---

    private async Task ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastMessage = message;
        _toastIsError = isError;
        StateHasChanged();

        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;
        try
        {
            await Task.Delay(4000, token);
            _toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    private void DismissToast()
    {
        _toastCts?.Cancel();
        _toastMessage = null;
    }

    // --- Profile ---

    private async Task SaveProfile()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
    }

    // --- Notifications ---

    private void ToggleMutedChannel(string channel)
    {
        if (!_mutedChannels.Remove(channel))
        {
            _mutedChannels.Add(channel);
        }
    }

    private async Task SaveNotificationPrefs()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!");
    }

    // --- Security ---

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            await ShowToast("Please fill in all password fields.", true);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", true);
            return;
        }
        if (_newPassword.Length < 8)
        {
            await ShowToast("New password must be at least 8 characters.", true);
            return;
        }

        _changingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _changePasswordExpanded = false;
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            await ShowToast("Password updated successfully!");
        }
        catch (Exception ex)
        {
            await ShowToast($"Failed to change password: {ex.Message}", true);
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void RequestRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeConfirm = true;
    }

    private void CancelRevoke()
    {
        _showRevokeConfirm = false;
        _sessionToRevoke = null;
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is null) return;
        _revoking = true;
        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            _showRevokeConfirm = false;
            _sessionToRevoke = null;
            await ShowToast("Session revoked successfully!");
        }
        catch (Exception ex)
        {
            await ShowToast($"Failed to revoke session: {ex.Message}", true);
        }
        finally
        {
            _revoking = false;
        }
    }

    // --- Appearance ---

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!");
    }

    // --- Render fragments ---

    private RenderFragment RenderProfileSection() => __builder =>
    {
        <section>
            <h3 class="section-title">Profile</h3>
            <p class="section-subtitle">Manage your public profile information.</p>

            <div class="settings-card">
                <div class="row">
                    <div class="col-md-8">
                        <div class="mb-3">
                            <label class="form-label fw-semibold">Display Name</label>
                            <input type="text" class="form-control" @bind="_displayName" placeholder="Your display name" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label fw-semibold">Email</label>
                            <input type="email" class="form-control" @bind="_email" placeholder="your@email.com" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label fw-semibold">Bio</label>
                            <textarea class="form-control" rows="4" @bind="_bio" placeholder="Tell us about yourself..."></textarea>
                        </div>
                    </div>
                    <div class="col-md-4">
                        <div class="avatar-preview-area">
                            <label class="form-label fw-semibold">Avatar Preview</label>
                            <div class="avatar-frame">
                                @if (!string.IsNullOrWhiteSpace(_avatarUrl))
                                {
                                    <img src="@_avatarUrl" alt="Avatar" class="avatar-img" />
                                }
                                else
                                {
                                    <div class="avatar-placeholder">👤</div>
                                }
                            </div>
                            <div class="mt-2">
                                <label class="form-label small text-muted">Avatar URL</label>
                                <input type="url" class="form-control form-control-sm" @bind="_avatarUrl" placeholder="https://example.com/avatar.png" />
                            </div>
                        </div>
                    </div>
                </div>

                <div class="d-flex gap-2 mt-3">
                    <button class="btn btn-primary" @onclick="SaveProfile">
                        Save Changes
                    </button>
                    <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">
                        Discard Changes
                    </button>
                </div>
            </div>
        </section>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <section>
            <h3 class="section-title">Notifications</h3>
            <p class="section-subtitle">Choose how and when you want to be notified.</p>

            <div class="settings-card">
                <h6 class="mb-3">Notification Channels</h6>
                <div class="toggle-row">
                    <div>
                        <div class="fw-semibold">Email Notifications</div>
                        <small class="text-muted">Receive notifications via email</small>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input toggle-switch" type="checkbox" role="switch"
                               checked="@_emailNotifications"
                               @onchange="e => _emailNotifications = (bool)(e.Value ?? false)" />
                    </div>
                </div>
                <div class="toggle-row">
                    <div>
                        <div class="fw-semibold">Push Notifications</div>
                        <small class="text-muted">Receive push notifications on your devices</small>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input toggle-switch" type="checkbox" role="switch"
                               checked="@_pushNotifications"
                               @onchange="e => _pushNotifications = (bool)(e.Value ?? false)" />
                    </div>
                </div>
                <div class="toggle-row">
                    <div>
                        <div class="fw-semibold">Weekly Digest</div>
                        <small class="text-muted">Get a weekly summary of activity</small>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input toggle-switch" type="checkbox" role="switch"
                               checked="@_weeklyDigest"
                               @onchange="e => _weeklyDigest = (bool)(e.Value ?? false)" />
                    </div>
                </div>
            </div>

            <div class="settings-card mt-3">
                <h6 class="mb-3">Muted Channels</h6>
                <p class="text-muted small">Select channels you want to mute.</p>
                <div class="channel-list">
                    @foreach (var channel in _allChannels)
                    {
                        var isMuted = _mutedChannels.Contains(channel);
                        <div class="form-check channel-item">
                            <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                                   checked="@isMuted"
                                   @onchange="() => ToggleMutedChannel(channel)" />
                            <label class="form-check-label" for="@($"ch-{channel}")">
                                <span class="channel-hash">#</span> @channel
                            </label>
                        </div>
                    }
                </div>
            </div>

            <div class="mt-3">
                <button class="btn btn-primary" @onclick="SaveNotificationPrefs">
                    Save Preferences
                </button>
            </div>
        </section>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <section>
            <h3 class="section-title">Security</h3>
            <p class="section-subtitle">Manage your password, two-factor authentication, and active sessions.</p>

            <!-- Change Password -->
            <div class="settings-card">
                <div class="d-flex justify-content-between align-items-center expandable-header"
                     @onclick="() => _changePasswordExpanded = !_changePasswordExpanded">
                    <div>
                        <h6 class="mb-0">Change Password</h6>
                        @if (_securitySettings?.LastPasswordChange is not null)
                        {
                            <small class="text-muted">Last changed: @_securitySettings.LastPasswordChange.Value.ToString("MMMM d, yyyy")</small>
                        }
                    </div>
                    <span class="expand-icon @(_changePasswordExpanded ? "expanded" : "")">▸</span>
                </div>

                @if (_changePasswordExpanded)
                {
                    <div class="mt-3 password-form">
                        <div class="mb-3">
                            <label class="form-label fw-semibold">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label fw-semibold">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label fw-semibold">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="ChangePassword" disabled="@_changingPassword">
                            @if (_changingPassword)
                            {
                                <span class="spinner-border spinner-border-sm me-1"></span>
                            }
                            Update Password
                        </button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="settings-card mt-3">
                <div class="toggle-row">
                    <div>
                        <h6 class="mb-0">Two-Factor Authentication</h6>
                        <div class="mt-1">
                            @if (_securitySettings?.TwoFactorEnabled == true)
                            {
                                <span class="badge bg-success">Enabled</span>
                            }
                            else
                            {
                                <span class="badge bg-warning text-dark">Disabled</span>
                            }
                        </div>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input toggle-switch" type="checkbox" role="switch"
                               checked="@(_securitySettings?.TwoFactorEnabled ?? false)" disabled />
                    </div>
                </div>
            </div>

            <!-- Active Sessions -->
            <div class="settings-card mt-3">
                <h6 class="mb-3">Active Sessions</h6>
                @if (_securitySettings?.Sessions is { Count: > 0 })
                {
                    <div class="table-responsive">
                        <table class="table table-hover mb-0">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th></th>
                                </tr>
                            </thead>
                            <tbody>
                                @{ var isFirst = true; }
                                @foreach (var session in _securitySettings.Sessions)
                                {
                                    <tr>
                                        <td>
                                            @session.Device
                                            @if (isFirst)
                                            {
                                                <span class="badge bg-info ms-1">Current</span>
                                            }
                                        </td>
                                        <td>@session.Location</td>
                                        <td>@session.LastActive.ToString("MMM d, yyyy h:mm tt")</td>
                                        <td>
                                            @if (!isFirst)
                                            {
                                                <button class="btn btn-outline-danger btn-sm"
                                                        @onclick="() => RequestRevoke(session)">
                                                    Revoke
                                                </button>
                                            }
                                        </td>
                                    </tr>
                                    isFirst = false;
                                }
                            </tbody>
                        </table>
                    </div>
                }
                else
                {
                    <p class="text-muted">No active sessions found.</p>
                }
            </div>
        </section>
    };

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <section>
            <h3 class="section-title">Appearance</h3>
            <p class="section-subtitle">Customize how the application looks and feels.</p>

            <div class="row">
                <div class="col-lg-7">
                    <!-- Theme -->
                    <div class="settings-card">
                        <h6 class="mb-3">Theme</h6>
                        <div class="d-flex gap-3">
                            @foreach (var theme in new[] { "Light", "Dark", "System" })
                            {
                                var t = theme;
                                <div class="form-check">
                                    <input class="form-check-input" type="radio" name="theme" id="@($"theme-{t}")"
                                           value="@t" checked="@(_theme == t)"
                                           @onchange="() => _theme = t" />
                                    <label class="form-check-label" for="@($"theme-{t}")">@t</label>
                                </div>
                            }
                        </div>
                    </div>

                    <!-- Font Size -->
                    <div class="settings-card mt-3">
                        <h6 class="mb-3">Font Size</h6>
                        <div class="d-flex gap-3">
                            @foreach (var size in new[] { "Small", "Medium", "Large" })
                            {
                                var s = size;
                                <div class="form-check">
                                    <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{s}")"
                                           value="@s" checked="@(_fontSize == s)"
                                           @onchange="() => _fontSize = s" />
                                    <label class="form-check-label" for="@($"fs-{s}")">@s</label>
                                </div>
                            }
                        </div>
                    </div>

                    <!-- Language -->
                    <div class="settings-card mt-3">
                        <h6 class="mb-3">Language</h6>
                        <select class="form-select" style="max-width: 300px;"
                                @bind="_language">
                            @foreach (var lang in _languages)
                            {
                                <option value="@lang">@lang</option>
                            }
                        </select>
                    </div>

                    <!-- Compact Mode -->
                    <div class="settings-card mt-3">
                        <div class="toggle-row">
                            <div>
                                <div class="fw-semibold">Compact Mode</div>
                                <small class="text-muted">Reduce spacing and padding throughout the UI</small>
                            </div>
                            <div class="form-check form-switch">
                                <input class="form-check-input toggle-switch" type="checkbox" role="switch"
                                       checked="@_compactMode"
                                       @onchange="e => _compactMode = (bool)(e.Value ?? false)" />
                            </div>
                        </div>
                    </div>

                    <div class="mt-3">
                        <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                    </div>
                </div>

                <!-- Live Preview -->
                <div class="col-lg-5">
                    <div class="settings-card mt-3 mt-lg-0">
                        <h6 class="mb-3">Live Preview</h6>
                        <div class="preview-area @GetPreviewClasses()">
                            <div class="preview-header">
                                <div class="preview-dot"></div>
                                <div class="preview-dot"></div>
                                <div class="preview-dot"></div>
                            </div>
                            <div class="preview-body">
                                <div class="preview-title">Dashboard</div>
                                <p class="preview-text">This is how your content will look with the selected settings.</p>
                                <div class="preview-card-inner">
                                    <div class="preview-label">Sample Card</div>
                                    <div class="preview-value">Content preview</div>
                                </div>
                                <div class="preview-meta">
                                    Theme: @_theme · Font: @_fontSize · @(_compactMode ? "Compact" : "Standard")
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </section>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();

        classes.Add(_theme switch
        {
            "Dark" => "preview-dark",
            "Light" => "preview-light",
            _ => "preview-system"
        });

        classes.Add(_fontSize switch
        {
            "Small" => "preview-font-sm",
            "Large" => "preview-font-lg",
            _ => "preview-font-md"
        });

        if (_compactMode) classes.Add("preview-compact");

        return string.Join(" ", classes);
    }
}

/* Layout */
.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 7rem);
    margin: -1.1rem -1.5rem 0;
    background: #f8f9fa;
}

.settings-sidebar {
    width: 240px;
    min-width: 240px;
    background: #fff;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
}

.sidebar-title {
    padding: 0 1.25rem;
    margin-bottom: 1rem;
    font-weight: 700;
    color: #333;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav .nav-item {
    margin: 0;
}

.settings-nav .nav-link {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    width: 100%;
    padding: 0.65rem 1.25rem;
    border: none;
    background: none;
    text-align: left;
    font-size: 0.95rem;
    color: #555;
    cursor: pointer;
    transition: all 0.15s ease;
    border-left: 3px solid transparent;
}

.settings-nav .nav-link:hover {
    background: #f0f4ff;
    color: #1b6ec2;
}

.settings-nav .nav-link.active {
    background: #e8f0fe;
    color: #1b6ec2;
    font-weight: 600;
    border-left-color: #1b6ec2;
}

.nav-icon {
    font-size: 1.1rem;
}

/* Content area */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 960px;
    position: relative;
}

.section-title {
    font-weight: 700;
    font-size: 1.5rem;
    margin-bottom: 0.25rem;
}

.section-subtitle {
    color: #6c757d;
    margin-bottom: 1.5rem;
}

.settings-card {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 0.5rem;
    padding: 1.25rem;
}

/* Toast */
.toast-message {
    position: sticky;
    top: 0;
    z-index: 100;
    margin-bottom: 1rem;
}

/* Profile */
.avatar-preview-area {
    text-align: center;
}

.avatar-frame {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    overflow: hidden;
    margin: 0.5rem auto;
    border: 3px solid #e0e0e0;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #f8f9fa;
}

.avatar-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 3rem;
    color: #adb5bd;
}

/* Toggle rows */
.toggle-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.toggle-row:last-child {
    border-bottom: none;
}

::deep .toggle-switch {
    width: 3rem;
    height: 1.5rem;
    cursor: pointer;
}

/* Channels */
.channel-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 0.5rem;
}

.channel-item {
    padding: 0.4rem 0.5rem;
    border-radius: 0.375rem;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #f8f9fa;
}

.channel-hash {
    color: #adb5bd;
    font-weight: 600;
}

/* Security */
.expandable-header {
    cursor: pointer;
    padding: 0.25rem 0;
    border-radius: 0.375rem;
    user-select: none;
}

.expandable-header:hover {
    background: #f8f9fa;
    margin: -0.25rem;
    padding: 0.5rem 0.25rem;
}

.expand-icon {
    font-size: 1.2rem;
    transition: transform 0.2s;
    color: #6c757d;
}

.expand-icon.expanded {
    transform: rotate(90deg);
}

.password-form {
    max-width: 400px;
    border-top: 1px solid #f0f0f0;
    padding-top: 1rem;
}

/* Appearance preview */
.preview-area {
    border-radius: 0.5rem;
    overflow: hidden;
    border: 1px solid #ccc;
    transition: all 0.3s ease;
}

.preview-header {
    display: flex;
    gap: 6px;
    padding: 0.5rem 0.75rem;
    border-bottom: 1px solid #ddd;
}

.preview-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: #ddd;
}

.preview-dot:nth-child(1) { background: #ff5f57; }
.preview-dot:nth-child(2) { background: #febc2e; }
.preview-dot:nth-child(3) { background: #28c840; }

.preview-body {
    padding: 1rem;
}

.preview-title {
    font-weight: 700;
    margin-bottom: 0.5rem;
}

.preview-text {
    margin-bottom: 0.75rem;
    line-height: 1.4;
}

.preview-card-inner {
    border: 1px solid #ddd;
    border-radius: 0.375rem;
    padding: 0.75rem;
    margin-bottom: 0.75rem;
}

.preview-label {
    font-weight: 600;
    font-size: 0.85em;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 0.25rem;
}

.preview-value {
    color: #6c757d;
}

.preview-meta {
    font-size: 0.8em;
    color: #adb5bd;
}

/* Light theme preview */
.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-light .preview-header {
    background: #f5f5f5;
}

/* Dark theme preview */
.preview-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-dark .preview-header {
    background: #181825;
    border-color: #45475a;
}

.preview-dark .preview-card-inner {
    border-color: #45475a;
    background: #313244;
}

.preview-dark .preview-value {
    color: #a6adc8;
}

.preview-dark .preview-meta {
    color: #6c7086;
}

/* System theme preview (matches light with a subtle indicator) */
.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #212529;
}

.preview-system .preview-header {
    background: #f5f5f5;
}

.preview-system .preview-body {
    background: #ffffff;
}

/* Font sizes */
.preview-font-sm { font-size: 0.85rem; }
.preview-font-md { font-size: 1rem; }
.preview-font-lg { font-size: 1.15rem; }

/* Compact mode */
.preview-compact .preview-body {
    padding: 0.5rem 0.75rem;
}

.preview-compact .preview-card-inner {
    padding: 0.4rem 0.6rem;
    margin-bottom: 0.4rem;
}

.preview-compact .preview-text {
    margin-bottom: 0.4rem;
}

/* Responsive */
@media (max-width: 768px) {
    .settings-dashboard {
        flex-direction: column;
    }

    .settings-sidebar {
        width: 100%;
        min-width: 100%;
        border-right: none;
        border-bottom: 1px solid #e0e0e0;
        padding: 1rem 0;
    }

    .settings-nav {
        display: flex;
        overflow-x: auto;
        padding: 0 0.5rem;
    }

    .settings-nav .nav-link {
        border-left: none;
        border-bottom: 3px solid transparent;
        white-space: nowrap;
        padding: 0.5rem 1rem;
    }

    .settings-nav .nav-link.active {
        border-left-color: transparent;
        border-bottom-color: #1b6ec2;
    }

    .settings-content {
        padding: 1rem;
    }
}

namespace sv_6ee6ed0400fd4cc59d2806b3ef6eeb25.Models;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);

public record NotificationPrefs(
    bool EmailNotifications,
    bool PushNotifications,
    bool WeeklyDigest,
    List<string> MutedChannels);

public record SecuritySettings(
    bool TwoFactorEnabled,
    DateTime? LastPasswordChange,
    List<ActiveSession> Sessions);

public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);

public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@rendermode InteractiveServer
@using sv_6ee6ed0400fd4cc59d2806b3ef6eeb25.Models
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <!-- Left sidebar navigation -->
    <nav class="settings-sidebar">
        <h5 class="sidebar-title">Settings</h5>
        <ul class="settings-nav">
            @foreach (var section in _sections)
            {
                <li class="nav-item">
                    <button class="nav-link @(ActiveSection == section.Key ? "active" : "")"
                            @onclick="() => ActiveSection = section.Key">
                        <span class="nav-icon">@section.Icon</span>
                        @section.Label
                    </button>
                </li>
            }
        </ul>
    </nav>

    <!-- Main content area -->
    <div class="settings-content">
        @if (_loading)
        {
            <div class="text-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else
        {
            <!-- Toast message -->
            @if (!string.IsNullOrEmpty(_toastMessage))
            {
                <div class="alert @(_toastIsError ? "alert-danger" : "alert-success") alert-dismissible fade show toast-message" role="alert">
                    @_toastMessage
                    <button type="button" class="btn-close" @onclick="DismissToast"></button>
                </div>
            }

            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfileSection()
                    break;
                case "notifications":
                    @RenderNotificationsSection()
                    break;
                case "security":
                    @RenderSecuritySection()
                    break;
                case "appearance":
                    @RenderAppearanceSection()
                    break;
            }
        }
    </div>
</div>

<!-- Revoke Session Confirmation Modal -->
@if (_showRevokeConfirm)
{
    <div class="modal-backdrop fade show"></div>
    <div class="modal fade show d-block" tabindex="-1" role="dialog">
        <div class="modal-dialog modal-dialog-centered" role="document">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke?.Device</strong> from <strong>@_sessionToRevoke?.Location</strong>?</p>
                    <p class="text-muted mb-0">This will sign out that device immediately.</p>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    <button type="button" class="btn btn-danger" @onclick="ConfirmRevoke" disabled="@_revoking">
                        @if (_revoking)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                        }
                        Revoke Session
                    </button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    // Section definitions
    private record SectionInfo(string Key, string Label, string Icon);

    private readonly SectionInfo[] _sections =
    [
        new("profile", "Profile", "👤"),
        new("notifications", "Notifications", "🔔"),
        new("security", "Security", "🔒"),
        new("appearance", "Appearance", "🎨")
    ];

    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;

    // Toast
    private string? _toastMessage;
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    // Profile state
    private UserProfile? _savedProfile;
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";

    // Notification state
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _allChannels = ["general", "announcements", "engineering", "design", "marketing", "support", "random"];
    private HashSet<string> _mutedChannels = [];

    // Security state
    private SecuritySettings? _securitySettings;
    private bool _changePasswordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _changingPassword;
    private bool _showRevokeConfirm;
    private ActiveSession? _sessionToRevoke;
    private bool _revoking;

    // Appearance state
    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Korean", "Portuguese"];

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        // Profile
        _savedProfile = await profileTask;
        ApplyProfile(_savedProfile);

        // Notifications
        var notif = await notifTask;
        _emailNotifications = notif.EmailNotifications;
        _pushNotifications = notif.PushNotifications;
        _weeklyDigest = notif.WeeklyDigest;
        _mutedChannels = new HashSet<string>(notif.MutedChannels);

        // Security
        _securitySettings = await securityTask;

        // Appearance
        var appearance = await appearanceTask;
        _theme = appearance.Theme;
        _fontSize = appearance.FontSize;
        _language = appearance.Language;
        _compactMode = appearance.CompactMode;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    // --- Toast helpers ---

    private async Task ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toastMessage = message;
        _toastIsError = isError;
        StateHasChanged();

        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;
        try
        {
            await Task.Delay(4000, token);
            _toastMessage = null;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

    private void DismissToast()
    {
        _toastCts?.Cancel();
        _toastMessage = null;
    }

    // --- Profile ---

    private async Task SaveProfile()
    {
        var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        await ShowToast("Profile saved successfully!");
    }

    private void DiscardProfileChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
    }

    // --- Notifications ---

    private void ToggleMutedChannel(string channel)
    {
        if (!_mutedChannels.Remove(channel))
        {
            _mutedChannels.Add(channel);
        }
    }

    private async Task SaveNotificationPrefs()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        await ShowToast("Notification preferences saved!");
    }

    // --- Security ---

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            await ShowToast("Please fill in all password fields.", true);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            await ShowToast("New passwords do not match.", true);
            return;
        }
        if (_newPassword.Length < 8)
        {
            await ShowToast("New password must be at least 8 characters.", true);
            return;
        }

        _changingPassword = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
            _changePasswordExpanded = false;
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            await ShowToast("Password updated successfully!");
        }
        catch (Exception ex)
        {
            await ShowToast($"Failed to change password: {ex.Message}", true);
        }
        finally
        {
            _changingPassword = false;
        }
    }

    private void RequestRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
        _showRevokeConfirm = true;
    }

    private void CancelRevoke()
    {
        _showRevokeConfirm = false;
        _sessionToRevoke = null;
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is null) return;
        _revoking = true;
        try
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _securitySettings = await SettingsService.GetSecuritySettingsAsync();
            _showRevokeConfirm = false;
            _sessionToRevoke = null;
            await ShowToast("Session revoked successfully!");
        }
        catch (Exception ex)
        {
            await ShowToast($"Failed to revoke session: {ex.Message}", true);
        }
        finally
        {
            _revoking = false;
        }
    }

    // --- Appearance ---

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        await ShowToast("Appearance settings saved!");
    }

    // --- Render fragments ---

    private RenderFragment RenderProfileSection() => __builder =>
    {
        <section>
            <h3 class="section-title">Profile</h3>
            <p class="section-subtitle">Manage your public profile information.</p>

            <div class="settings-card">
                <div class="row">
                    <div class="col-md-8">
                        <div class="mb-3">
                            <label class="form-label fw-semibold">Display Name</label>
                            <input type="text" class="form-control" @bind="_displayName" placeholder="Your display name" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label fw-semibold">Email</label>
                            <input type="email" class="form-control" @bind="_email" placeholder="your@email.com" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label fw-semibold">Bio</label>
                            <textarea class="form-control" rows="4" @bind="_bio" placeholder="Tell us about yourself..."></textarea>
                        </div>
                    </div>
                    <div class="col-md-4">
                        <div class="avatar-preview-area">
                            <label class="form-label fw-semibold">Avatar Preview</label>
                            <div class="avatar-frame">
                                @if (!string.IsNullOrWhiteSpace(_avatarUrl))
                                {
                                    <img src="@_avatarUrl" alt="Avatar" class="avatar-img" />
                                }
                                else
                                {
                                    <div class="avatar-placeholder">👤</div>
                                }
                            </div>
                            <div class="mt-2">
                                <label class="form-label small text-muted">Avatar URL</label>
                                <input type="url" class="form-control form-control-sm" @bind="_avatarUrl" placeholder="https://example.com/avatar.png" />
                            </div>
                        </div>
                    </div>
                </div>

                <div class="d-flex gap-2 mt-3">
                    <button class="btn btn-primary" @onclick="SaveProfile">
                        Save Changes
                    </button>
                    <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">
                        Discard Changes
                    </button>
                </div>
            </div>
        </section>
    };

    private RenderFragment RenderNotificationsSection() => __builder =>
    {
        <section>
            <h3 class="section-title">Notifications</h3>
            <p class="section-subtitle">Choose how and when you want to be notified.</p>

            <div class="settings-card">
                <h6 class="mb-3">Notification Channels</h6>
                <div class="toggle-row">
                    <div>
                        <div class="fw-semibold">Email Notifications</div>
                        <small class="text-muted">Receive notifications via email</small>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input toggle-switch" type="checkbox" role="switch"
