            <div class="mt-3">
                <button class="btn btn-primary" @onclick="SaveNotificationPrefs">
                    Save Preferences
                </button>
            </div>
        </section>
    };

    private RenderFragment RenderSecuritySection() => __builder =>
    {
        <section>
            <h3 class="section-title">Security</h3>
            <p class="section-subtitle">Manage your password, two-factor authentication, and active sessions.</p>

            <!-- Change Password -->
            <div class="settings-card">
                <div class="d-flex justify-content-between align-items-center expandable-header"
