                    </div>
                    <span class="expand-icon @(_changePasswordExpanded ? "expanded" : "")">▸</span>
                </div>

                @if (_changePasswordExpanded)
                {
                    <div class="mt-3 password-form">
                        <div class="mb-3">
                            <label class="form-label fw-semibold">Current Password</label>
                            <input type="password" class="form-control" @bind="_currentPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label fw-semibold">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label fw-semibold">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="ChangePassword" disabled="@_changingPassword">
                            @if (_changingPassword)
                            {
                                <span class="spinner-border spinner-border-sm me-1"></span>
                            }
                            Update Password
                        </button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="settings-card mt-3">
                <div class="toggle-row">
                    <div>
                        <h6 class="mb-0">Two-Factor Authentication</h6>
                        <div class="mt-1">
                            @if (_securitySettings?.TwoFactorEnabled == true)
                            {
                                <span class="badge bg-success">Enabled</span>
                            }
                            else
                            {
                                <span class="badge bg-warning text-dark">Disabled</span>
                            }
                        </div>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input toggle-switch" type="checkbox" role="switch"
                               checked="@(_securitySettings?.TwoFactorEnabled ?? false)" disabled />
                    </div>
                </div>
            </div>

            <!-- Active Sessions -->
            <div class="settings-card mt-3">
                <h6 class="mb-3">Active Sessions</h6>
                @if (_securitySettings?.Sessions is { Count: > 0 })
                {
                    <div class="table-responsive">
                        <table class="table table-hover mb-0">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th></th>
                                </tr>
                            </thead>
                            <tbody>
                                @{ var isFirst = true; }
                                @foreach (var session in _securitySettings.Sessions)
                                {
