                        <div class="mb-3">
                            <label class="form-label fw-semibold">New Password</label>
                            <input type="password" class="form-control" @bind="_newPassword" />
                        </div>
                        <div class="mb-3">
                            <label class="form-label fw-semibold">Confirm New Password</label>
                            <input type="password" class="form-control" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="ChangePassword" disabled="@_changingPassword">
                            @if (_changingPassword)
                            {
                                <span class="spinner-border spinner-border-sm me-1"></span>
                            }
                            Update Password
                        </button>
                    </div>
                }
            </div>

            <!-- Two-Factor Authentication -->
            <div class="settings-card mt-3">
                <div class="toggle-row">
                    <div>
                        <h6 class="mb-0">Two-Factor Authentication</h6>
                        <div class="mt-1">
                            @if (_securitySettings?.TwoFactorEnabled == true)
                            {
                                <span class="badge bg-success">Enabled</span>
                            }
                            else
                            {
                                <span class="badge bg-warning text-dark">Disabled</span>
                            }
                        </div>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input toggle-switch" type="checkbox" role="switch"
                               checked="@(_securitySettings?.TwoFactorEnabled ?? false)" disabled />
                    </div>
                </div>
            </div>

            <!-- Active Sessions -->
            <div class="settings-card mt-3">
                <h6 class="mb-3">Active Sessions</h6>
                @if (_securitySettings?.Sessions is { Count: > 0 })
                {
                    <div class="table-responsive">
                        <table class="table table-hover mb-0">
                            <thead>
                                <tr>
                                    <th>Device</th>
                                    <th>Location</th>
                                    <th>Last Active</th>
                                    <th></th>
                                </tr>
                            </thead>
                            <tbody>
                                @{ var isFirst = true; }
                                @foreach (var session in _securitySettings.Sessions)
                                {
                                    <tr>
                                        <td>
                                            @session.Device
                                            @if (isFirst)
                                            {
                                                <span class="badge bg-info ms-1">Current</span>
                                            }
                                        </td>
                                        <td>@session.Location</td>
                                        <td>@session.LastActive.ToString("MMM d, yyyy h:mm tt")</td>
                                        <td>
                                            @if (!isFirst)
                                            {
                                                <button class="btn btn-outline-danger btn-sm"
                                                        @onclick="() => RequestRevoke(session)">
                                                    Revoke
                                                </button>
                                            }
                                        </td>
                                    </tr>
                                    isFirst = false;
                                }
                            </tbody>
                        </table>
                    </div>
                }
                else
                {
                    <p class="text-muted">No active sessions found.</p>
                }
            </div>
        </section>
    };

    private RenderFragment RenderAppearanceSection() => __builder =>
    {
        <section>
            <h3 class="section-title">Appearance</h3>
            <p class="section-subtitle">Customize how the application looks and feels.</p>

            <div class="row">
                <div class="col-lg-7">
                    <!-- Theme -->
                    <div class="settings-card">
                        <h6 class="mb-3">Theme</h6>
                        <div class="d-flex gap-3">
                            @foreach (var theme in new[] { "Light", "Dark", "System" })
                            {
                                var t = theme;
                                <div class="form-check">
                                    <input class="form-check-input" type="radio" name="theme" id="@($"theme-{t}")"
                                           value="@t" checked="@(_theme == t)"
                                           @onchange="() => _theme = t" />
                                    <label class="form-check-label" for="@($"theme-{t}")">@t</label>
                                </div>
                            }
                        </div>
                    </div>

                    <!-- Font Size -->
                    <div class="settings-card mt-3">
                        <h6 class="mb-3">Font Size</h6>
                        <div class="d-flex gap-3">
                            @foreach (var size in new[] { "Small", "Medium", "Large" })
                            {
                                var s = size;
                                <div class="form-check">
                                    <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{s}")"
                                           value="@s" checked="@(_fontSize == s)"
                                           @onchange="() => _fontSize = s" />
                                    <label class="form-check-label" for="@($"fs-{s}")">@s</label>
                                </div>
                            }
                        </div>
                    </div>

                    <!-- Language -->
                    <div class="settings-card mt-3">
                        <h6 class="mb-3">Language</h6>
                        <select class="form-select" style="max-width: 300px;"
                                @bind="_language">
                            @foreach (var lang in _languages)
                            {
                                <option value="@lang">@lang</option>
                            }
                        </select>
                    </div>

                    <!-- Compact Mode -->
                    <div class="settings-card mt-3">
                        <div class="toggle-row">
                            <div>
                                <div class="fw-semibold">Compact Mode</div>
                                <small class="text-muted">Reduce spacing and padding throughout the UI</small>
                            </div>
                            <div class="form-check form-switch">
                                <input class="form-check-input toggle-switch" type="checkbox" role="switch"
                                       checked="@_compactMode"
                                       @onchange="e => _compactMode = (bool)(e.Value ?? false)" />
                            </div>
                        </div>
                    </div>

                    <div class="mt-3">
                        <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                    </div>
                </div>

                <!-- Live Preview -->
                <div class="col-lg-5">
                    <div class="settings-card mt-3 mt-lg-0">
                        <h6 class="mb-3">Live Preview</h6>
                        <div class="preview-area @GetPreviewClasses()">
                            <div class="preview-header">
                                <div class="preview-dot"></div>
                                <div class="preview-dot"></div>
                                <div class="preview-dot"></div>
                            </div>
                            <div class="preview-body">
                                <div class="preview-title">Dashboard</div>
                                <p class="preview-text">This is how your content will look with the selected settings.</p>
                                <div class="preview-card-inner">
                                    <div class="preview-label">Sample Card</div>
                                    <div class="preview-value">Content preview</div>
                                </div>
                                <div class="preview-meta">
                                    Theme: @_theme · Font: @_fontSize · @(_compactMode ? "Compact" : "Standard")
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </section>
    };

    private string GetPreviewClasses()
    {
        var classes = new List<string>();

        classes.Add(_theme switch
        {
            "Dark" => "preview-dark",
            "Light" => "preview-light",
            _ => "preview-system"
        });

        classes.Add(_fontSize switch
        {
            "Small" => "preview-font-sm",
            "Large" => "preview-font-lg",
            _ => "preview-font-md"
        });

        if (_compactMode) classes.Add("preview-compact");

        return string.Join(" ", classes);
    }
}
"}

