toolArgs.file_text:
/* Layout */
.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 7rem);
    margin: -1.1rem -1.5rem 0;
    background: #f8f9fa;
}

.settings-sidebar {
    width: 240px;
    min-width: 240px;
    background: #fff;
    border-right: 1px solid #e0e0e0;
    padding: 1.5rem 0;
}

.sidebar-title {
    padding: 0 1.25rem;
    margin-bottom: 1rem;
    font-weight: 700;
    color: #333;
}

.settings-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.settings-nav .nav-item {
    margin: 0;
}

.settings-nav .nav-link {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    width: 100%;
    padding: 0.65rem 1.25rem;
    border: none;
    background: none;
    text-align: left;
    font-size: 0.95rem;
    color: #555;
    cursor: pointer;
    transition: all 0.15s ease;
    border-left: 3px solid transparent;
}

.settings-nav .nav-link:hover {
    background: #f0f4ff;
    color: #1b6ec2;
}

.settings-nav .nav-link.active {
    background: #e8f0fe;
    color: #1b6ec2;
    font-weight: 600;
    border-left-color: #1b6ec2;
}

.nav-icon {
    font-size: 1.1rem;
}

/* Content area */
.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 960px;
    position: relative;
}

.section-title {
    font-weight: 700;
    font-size: 1.5rem;
    margin-bottom: 0.25rem;
}

.section-subtitle {
    color: #6c757d;
    margin-bottom: 1.5rem;
}

.settings-card {
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 0.5rem;
    padding: 1.25rem;
}

/* Toast */
.toast-message {
    position: sticky;
    top: 0;
    z-index: 100;
    margin-bottom: 1rem;
}

/* Profile */
.avatar-preview-area {
    text-align: center;
}

.avatar-frame {
    width: 120px;
    height: 120px;
    border-radius: 50%;
    overflow: hidden;
    margin: 0.5rem auto;
    border: 3px solid #e0e0e0;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #f8f9fa;
}

.avatar-img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.avatar-placeholder {
    font-size: 3rem;
    color: #adb5bd;
}

/* Toggle rows */
.toggle-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.toggle-row:last-child {
    border-bottom: none;
}

::deep .toggle-switch {
    width: 3rem;
    height: 1.5rem;
    cursor: pointer;
}

/* Channels */
.channel-list {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 0.5rem;
}

.channel-item {
    padding: 0.4rem 0.5rem;
    border-radius: 0.375rem;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #f8f9fa;
}

.channel-hash {
    color: #adb5bd;
    font-weight: 600;
}

/* Security */
.expandable-header {
    cursor: pointer;
    padding: 0.25rem 0;
    border-radius: 0.375rem;
    user-select: none;
}

.expandable-header:hover {
    background: #f8f9fa;
    margin: -0.25rem;
    padding: 0.5rem 0.25rem;
}

.expand-icon {
    font-size: 1.2rem;
    transition: transform 0.2s;
    color: #6c757d;
}

.expand-icon.expanded {
    transform: rotate(90deg);
}

.password-form {
    max-width: 400px;
    border-top: 1px solid #f0f0f0;
    padding-top: 1rem;
}

/* Appearance preview */
.preview-area {
    border-radius: 0.5rem;
    overflow: hidden;
    border: 1px solid #ccc;
    transition: all 0.3s ease;
}

.preview-header {
    display: flex;
    gap: 6px;
    padding: 0.5rem 0.75rem;
    border-bottom: 1px solid #ddd;
}

.preview-dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
    background: #ddd;
}

.preview-dot:nth-child(1) { background: #ff5f57; }
.preview-dot:nth-child(2) { background: #febc2e; }
.preview-dot:nth-child(3) { background: #28c840; }

.preview-body {
    padding: 1rem;
}

.preview-title {
    font-weight: 700;
    margin-bottom: 0.5rem;
}

.preview-text {
    margin-bottom: 0.75rem;
    line-height: 1.4;
}

.preview-card-inner {
    border: 1px solid #ddd;
    border-radius: 0.375rem;
    padding: 0.75rem;
    margin-bottom: 0.75rem;
}

.preview-label {
    font-weight: 600;
    font-size: 0.85em;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 0.25rem;
}

.preview-value {
    color: #6c757d;
}

.preview-meta {
    font-size: 0.8em;
    color: #adb5bd;
}

/* Light theme preview */
.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-light .preview-header {
    background: #f5f5f5;
}

/* Dark theme preview */
.preview-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.preview-dark .preview-header {
    background: #181825;
    border-color: #45475a;
}

.preview-dark .preview-card-inner {
    border-color: #45475a;
    background: #313244;
}

.preview-dark .preview-value {
    color: #a6adc8;
}

.preview-dark .preview-meta {
    color: #6c7086;
}

/* System theme preview (matches light with a subtle indicator) */
.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #212529;
}

.preview-system .preview-header {
    background: #f5f5f5;
}

.preview-system .preview-body {
    background: #ffffff;
}

/* Font sizes */
.preview-font-sm { font-size: 0.85rem; }
.preview-font-md { font-size: 1rem; }
.preview-font-lg { font-size: 1.15rem; }

/* Compact mode */
.preview-compact .preview-body {
    padding: 0.5rem 0.75rem;
}

.preview-compact .preview-card-inner {
    padding: 0.4rem 0.6rem;
    margin-bottom: 0.4rem;
}

.preview-compact .preview-text {
